    /** Returns estimated verse start time in ms, or 0 if unknown. */
    fun getStartMs(gospel: Gospel, chapter: Int, verse: Int): Int {
        val arr = when (gospel) {
            Gospel.MATTHEW -> matthew
            Gospel.MARK    -> mark
            Gospel.LUKE    -> luke
            Gospel.JOHN    -> john
        }
        val chIdx = chapter - 1
        if (chIdx !in arr.indices) return 0
        val vIdx = verse - 1
        return if (vIdx in arr[chIdx].indices) arr[chIdx][vIdx] else 0
    }
}